import{_ as o,o as t,c as n,a5 as r}from"./chunks/framework.DJo0M80U.js";const I=JSON.parse('{"title":"int 和 Integer","description":"","frontmatter":{"title":"`int` 和 `Integer`","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/数据类型/`int` 和 `Integer`.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/数据类型/`int` 和 `Integer`.md"}'),d={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/数据类型/`int` 和 `Integer`.md"};function a(i,e,c,l,s,g){return t(),n("div",null,[...e[0]||(e[0]=[r('<div><p>在Java中， 两者都用于表示整数值，但它们在语言中的角色和用途有重要的区别：</p><h3 id="int" tabindex="-1">int <a class="header-anchor" href="#int" aria-label="Permalink to &quot;int&quot;">​</a></h3><ul><li><strong>基本数据类型</strong>：<code>int</code> 是Java的一种基本数据类型，用于存储整数值。</li><li><strong>性能</strong>：直接存储数值，访问速度快，效率高，因为它直接在栈上存储数据。</li><li><strong>默认值</strong>：未初始化的 <code>int</code> 变量默认值为 0。</li><li><strong>范围</strong>：可以存储从 -2,147,483,648 到 2,147,483,647 的整数。</li><li><strong>操作</strong>：可以直接参与数学运算和比较操作。</li></ul><h3 id="integer" tabindex="-1">Integer <a class="header-anchor" href="#integer" aria-label="Permalink to &quot;Integer&quot;">​</a></h3><ul><li><strong>引用数据类型</strong>：<code>Integer</code> 是 <code>int</code> 的包装类，属于Java的类库 <code>java.lang</code> 中的一部分。</li><li><strong>对象</strong>：每个 <code>Integer</code> 实例都包含一个 <code>int</code> 类型的字段。作为对象，它存在于堆上，并且可以调用方法和处理。</li><li><strong>空值</strong>：<code>Integer</code> 可以为 <code>null</code>，表示它可以没有任何值，这在处理可能未初始化或可选的数据时非常有用。</li><li><strong>默认值</strong>：未显式初始化的 <code>Integer</code> 对象的默认值是 <code>null</code>。</li><li><strong>自动装箱和拆箱</strong>：</li><li><strong>装箱</strong>：自动将 <code>int</code> 转换为 <code>Integer</code> 的过程称为自动装箱（例如，当将 <code>int</code> 值赋给 <code>Integer</code> 变量时）。</li><li><strong>拆箱</strong>：自动将 <code>Integer</code> 转换为 <code>int</code> 的过程称为拆箱（例如，当将 <code>Integer</code> 对象用在需要 <code>int</code> 值的环境中时）。</li><li><strong>实用方法</strong>：<code>Integer</code> 类提供了多种方法，如 <code>parseInt()</code>, <code>valueOf()</code>, <code>compareTo()</code>, 等等，这些方法可以处理整数并执行转换和比较等操作。</li></ul><h3 id="关系" tabindex="-1">关系 <a class="header-anchor" href="#关系" aria-label="Permalink to &quot;关系&quot;">​</a></h3><ul><li>虽然 <code>int</code> 和 <code>Integer</code> 都用于处理整数，但 <code>Integer</code> 提供了更多的功能，如可以作为泛型的参数，可以用作集合中的元素等。</li><li>在性能敏感的场景下，通常优先使用 <code>int</code>，因为它避免了额外的对象创建和管理开销。</li><li>在需要对象特性或需要包含空值时使用 <code>Integer</code>，例如在集合框架中或与API交互时，这些场景需要使用对象而不是原始类型。</li></ul><p>总的来说，<code>int</code> 和 <code>Integer</code> 的选择取决于具体的使用场景和性能要求。在实际开发中，合理利用自动装箱和拆箱特性，可以使代码既简洁又高效。</p></div>',1)])])}const p=o(d,[["render",a]]);export{I as __pageData,p as default};
